/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const IntuitionBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *IntuitionBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// A new class made from a superclass, named `class_id`, or private when
    /// that is null. The superclass is the public one named `super_id`, or
    /// else `super_class`; only rootclass has neither. Null if the name is
    /// taken, the superclass is not found, or there is no memory. The class
    /// comes back with a dispatcher that answers 0 to everything and off the
    /// public list: set its dispatcher, then AddClass it if it is public.
    pub fn MakeClass(self: *IntuitionBase, class_id: ?[*:0]const u8, super_id: ?[*:0]const u8, super_class: ?*intuition.Class, inst_size: u32) ?*intuition.Class {
        return libraries.call(self, LVO.MakeClass, Fn.MakeClass, .{ class_id, super_id, super_class, inst_size });
    }

    /// Take a class off the public list and free it. False, with the class
    /// off the list and still there, while it has objects or subclasses. Null
    /// is true.
    pub fn FreeClass(self: *IntuitionBase, cl: ?*intuition.Class) bool {
        return libraries.call(self, LVO.FreeClass, Fn.FreeClass, .{cl});
    }

    /// Put a named class on the public list. A private one, or one already
    /// there, is left alone.
    pub fn AddClass(self: *IntuitionBase, cl: *intuition.Class) void {
        return libraries.call(self, LVO.AddClass, Fn.AddClass, .{cl});
    }

    /// Take a class off the public list. One not on it is left alone.
    pub fn RemoveClass(self: *IntuitionBase, cl: *intuition.Class) void {
        return libraries.call(self, LVO.RemoveClass, Fn.RemoveClass, .{cl});
    }

    /// The public class of that name, or null.
    pub fn FindClass(self: *IntuitionBase, class_id: [*:0]const u8) ?*intuition.Class {
        return libraries.call(self, LVO.FindClass, Fn.FindClass, .{class_id});
    }

    /// Hold the public class list, and answer it. Nothing is added to it or
    /// taken off it until UnlockClassList.
    pub fn LockClassList(self: *IntuitionBase) *exec.MinList {
        return libraries.call(self, LVO.LockClassList, Fn.LockClassList, .{});
    }

    /// Let the public class list go again.
    pub fn UnlockClassList(self: *IntuitionBase) void {
        return libraries.call(self, LVO.UnlockClassList, Fn.UnlockClassList, .{});
    }

    /// A new object of the class `cl`, or of the public class named
    /// `class_id` when `cl` is null, with `tags` as its first attributes.
    /// Null if there is no such class, or it would not make one.
    pub fn NewObjectTagList(self: *IntuitionBase, cl: ?*intuition.Class, class_id: ?[*:0]const u8, tags: ?[*]const utility.TagItem) ?*intuition.Object {
        return libraries.call(self, LVO.NewObjectTagList, Fn.NewObjectTagList, .{ cl, class_id, tags });
    }

    /// Free an object, and what its classes had it hold. Null does nothing.
    pub fn DisposeObject(self: *IntuitionBase, object: ?*intuition.Object) void {
        return libraries.call(self, LVO.DisposeObject, Fn.DisposeObject, .{object});
    }

    /// Change an object's attributes. Nonzero when something that shows
    /// changed, as its class decides.
    pub fn SetAttrsTagList(self: *IntuitionBase, object: ?*intuition.Object, tags: ?[*]const utility.TagItem) u32 {
        return libraries.call(self, LVO.SetAttrsTagList, Fn.SetAttrsTagList, .{ object, tags });
    }

    /// Read one attribute into `storage`. 0 when its class does not know it.
    pub fn GetAttr(self: *IntuitionBase, attr_id: utility.Tag, object: ?*intuition.Object, storage: *usize) u32 {
        return libraries.call(self, LVO.GetAttr, Fn.GetAttr, .{ attr_id, object, storage });
    }

    /// The next object on a list of objects (OM_ADDTAIL), from a node pointer
    /// that starts at the list's head and is moved along. Null at the end.
    pub fn NextObject(self: *IntuitionBase, state: *?*exec.MinNode) ?*intuition.Object {
        return libraries.call(self, LVO.NextObject, Fn.NextObject, .{state});
    }

    /// Send a message to an object, to be handled by its own class. 0 for a
    /// null object; otherwise whatever the class answers.
    pub fn SendMessage(self: *IntuitionBase, object: ?*intuition.Object, msg: *intuition.Msg) usize {
        return libraries.call(self, LVO.SendMessage, Fn.SendMessage, .{ object, msg });
    }

    /// Send a message to an object as `cl`'s superclass would handle it: how
    /// a dispatcher passes on what it does not handle itself.
    pub fn SendSuperMessage(self: *IntuitionBase, cl: *intuition.Class, object: ?*intuition.Object, msg: *intuition.Msg) usize {
        return libraries.call(self, LVO.SendSuperMessage, Fn.SendSuperMessage, .{ cl, object, msg });
    }

    /// Send a message to an object as `cl` would handle it, whatever the
    /// object's own class is.
    pub fn CoerceMessage(self: *IntuitionBase, cl: *intuition.Class, object: ?*intuition.Object, msg: *intuition.Msg) usize {
        return libraries.call(self, LVO.CoerceMessage, Fn.CoerceMessage, .{ cl, object, msg });
    }

    /// Draw an image at (left, top) in the RastPort, added to the image's own
    /// left and top: IM_DRAW in the normal state. Null does nothing.
    pub fn DrawImage(self: *IntuitionBase, rp: *graphics.RastPort, image: ?*intuition.Object, left: i32, top: i32) void {
        return libraries.call(self, LVO.DrawImage, Fn.DrawImage, .{ rp, image, left, top });
    }

    /// The same in a state (IDS_), with a screen's pens where the image wants
    /// them (may be null).
    pub fn DrawImageState(self: *IntuitionBase, rp: *graphics.RastPort, image: ?*intuition.Object, left: i32, top: i32, state: u32, draw_info: ?*intuition.imageclass.DrawInfo) void {
        return libraries.call(self, LVO.DrawImageState, Fn.DrawImageState, .{ rp, image, left, top, state, draw_info });
